basicCode.vanilla:
import { createThinkingIndicator } from '@/components/ui/thinking-indicator';

const indicator = createThinkingIndicator({ label: 'Gerando resposta' });
document.querySelector('#answer')?.append(indicator);

arrivalCode.vanilla:
// O indicador NÃO se apaga sozinho: quem monta a conversa é quem o tira,
// porque só ele sabe que o primeiro trecho chegou.
indicator.remove();
answer.textContent = trecho;

arrivalCode.react:
// O indicador NÃO se apaga sozinho: quem monta a conversa é quem o tira,
// porque só ele sabe que o primeiro trecho chegou.
{texto ? <p>{texto}</p> : <ThinkingIndicator label="Gerando resposta" />}

extensibilityCode.web:
/* O tamanho do ponto e o ritmo da onda são da folha, e mudam para todas as
   esperas de uma vez. Sobrescrever aqui é decisão de sistema, não de tela. */
.nds-thinking-dots > span {
  inline-size: var(--spacing-3);
  block-size: var(--spacing-3);
}

customizationCode.web:
.nds-thinking {
  justify-content: center;
}

/* Sob movimento reduzido os pontos param e ficam visíveis. Apagá-los aqui
   pareceria desligado justamente para quem escolheu menos movimento, e a
   frase continuaria sendo a única coisa a dizer o que acontece. */
@media (prefers-reduced-motion: reduce) {
  .nds-thinking-dots > span {
    opacity: 0.6;
  }
}

